SELECT  FROM questionnaire_response
WHERE tenant_id = #{tenantId} AND people_id = #{peopleId}
  AND purpose = #{purpose} AND status = 'DRAFT' AND is_deleted = 0
AND followup_record_id = #{followupRecordId}
AND followup_record_id IS NULL
AND request_id = #{requestId}
AND request_id IS NULL
ORDER BY gmt_created DESC LIMIT 1

SELECT  FROM questionnaire_response
WHERE tenant_id = #{tenantId} AND people_id = #{peopleId}
  AND purpose = #{purpose} AND status = 'SUBMITTED' AND is_deleted = 0
ORDER BY submitted_at DESC
LIMIT #{limit}
